export function levenshtein(t,n){if(0===t.length)return n.length;if(0===n.length)return t.length;const h=[];let e,r;for(e=0;e<=n.length;e++)h[e]=[e];for(r=0;r<=t.length;r++)h[0][r]=r;for(e=1;e<=n.length;e++)for(r=1;r<=t.length;r++)n.charAt(e-1)===t.charAt(r-1)?h[e][r]=h[e-1][r-1]:e>1&&r>1&&n.charAt(e-2)===t.charAt(r-1)&&n.charAt(e-1)===t.charAt(r-2)?h[e][r]=h[e-2][r-2]+1:h[e][r]=Math.min(h[e-1][r-1]+1,Math.min(h[e][r-1]+1,h[e-1][r]+1));return h[n.length][t.length]}